       border-radius: 12px;
       padding: 12px 18px;
       font: inherit;
       font-weight: 700;
       color: white;
       background: linear-gradient(135deg, var(--accent), var(--accent-strong));
       cursor: pointer;
       box-shadow: 0 10px 24px rgba(124, 58, 237, 0.25);
       transition: transform 0.15s ease, box-shadow 0.15s ease;
     }

     button:hover {
       transform: translateY(-1px);
       box-shadow: 0 14px 28px rgba(124, 58, 237, 0.3);
     }

     button:focus-visible,
     input[type="checkbox"]:focus-visible {
       outline: 3px solid var(--focus);
       outline-offset: 3px;
     }

     .status {
       min-height: 1.25rem;
       color: #c4b5fd;
       font-size: 0.92rem;
     }
   </style>
 </head>
 <body>
   <main class="card">
     <h1>Terms of Use</h1>
     <p>Please review and accept the terms before continuing.</p>

     <form id="consent-form" novalidate>
       <div class="form-field">
         <div class="checkbox-row">
           <input id="consent" name="consent" type="checkbox" required />
           <div>
             <label for="consent">I agree to the Terms of Use</label>
             <p class="helper-text">Required to submit this form.</p>
           </div>
         </div>
       </div>

       <button type="submit">Submit</button>
       <div class="status" id="status" aria-live="polite"></div>
     </form>
   </main>

   <script>
     const form = document.getElementById('consent-form');
     const consent = document.getElementById('consent');
     const status = document.getElementById('status');

     form.addEventListener('submit', (event) => {
       if (!consent.checked) {
         event.preventDefault();
         status.textContent = 'Please accept the Terms of Use to continue.';
         consent.focus();
         return;
       }

       event.preventDefault();
       status.textContent = 'Consent received.';
     });

     consent.addEventListener('change', () => {
       status.textContent = '';
     });
   </script>
 </body>
